static inline vu_str *vu_at_L_Str(L_Str *l, int64_t i, int line) {
    if (__builtin_expect(i < 0 || i >= l->len, 0)) vu_oob(i, l->len, line);
    return &l->data[i];
}
static void vu_grow_L_Str(L_Str *l) {
    if (l->cap > (int64_t)(PTRDIFF_MAX / sizeof(vu_str) / 2)) vu_oom();
    int64_t c = l->cap ? l->cap * 2 : 4;
    vu_str *d = (vu_str *)realloc(l->data, (size_t)c * sizeof(vu_str));
    if (!d) vu_oom();
    l->data = d;
    l->cap = c;
}
static void vu_reserve_L_Str(L_Str *l, int64_t n, int line) {
    if (n < 0) vu_fail(line, "reserve(%lld): the count can't be negative", (long long)n);
    if (n <= l->cap - l->len) return;
    if (n > (int64_t)(PTRDIFF_MAX / sizeof(vu_str)) - l->len) vu_oom();
    int64_t c = l->len + n;
    vu_str *d = (vu_str *)realloc(l->data, (size_t)c * sizeof(vu_str));
    if (!d) vu_oom();
    l->data = d;
    l->cap = c;
}
static inline vu_str vu_pop_L_Str(L_Str *l, int line) {
    if (__builtin_expect(l->len == 0, 0)) vu_fail(line, "pop() from an empty list");
    return l->data[--l->len];
}
static inline void vu_push_L_Str(L_Str *l, vu_str v) {
    if (l->len == l->cap) vu_grow_L_Str(l);
    l->data[l->len++] = v;
}
static L_Str vu_rep_L_Str(L_Str src, int64_t n, int line) {
    L_Str r = {0};
    if (n > 0 && src.len > 0) {
        if (n > INT64_MAX / src.len || src.len * n > (int64_t)(PTRDIFF_MAX / sizeof(vu_str)))
            vu_fail(line, "list of %lld x %lld elements is too large", (long long)src.len, (long long)n);
        int64_t total = src.len * n;
        r.data = (vu_str *)vu_malloc((size_t)total * sizeof(vu_str));
        r.len = r.cap = total;
        if (src.len == 1) { vu_str v = src.data[0]; for (int64_t k = 0; k < total; k++) r.data[k] = v; }
        else for (int64_t k = 0; k < n; k++) memcpy(r.data + k * src.len, src.data, (size_t)src.len * sizeof(vu_str));
    }
    free(src.data);
    return r;
}
